int n,m,P;
void mulself(int &a,int b){
  a = a * b % P;
}
int mul(int a,int b){
  return a * b % P;
}
void add(int &a,int b){
  a += b;
  if(a >= P)
    a -= P;
}
const int MAX = 511;
int dwu[MAX][MAX];
int dp1[MAX];
int dp2[MAX][MAX];
int dp3[MAX][MAX];
int ile[MAX];
int32_t main() {
  ios_base::sync_with_stdio(0);
  cin.tie(0);
  cout << fixed << setprecision(11);
  cerr << fixed << setprecision(6);
  cin >> n >> m >> P;
  R(i,n + 1)R(j,i + 1){
    if(j == 0){
      dwu[i][j] = 1;
    }else{
      dwu[i][j] = dwu[i-1][j];
      add(dwu[i][j], dwu[i-1][j-1]);
    }
  }

  dp1[0] = 0;
  ile[0] = 1;
  R(i,m+1)if(i){
